describe('Order Confirmation after Successful Payment', () => {
    beforeEach(() => {
        cy.visit('/payment'); // Navigate to the payment page
    });

    it('should display order confirmation after successful payment', () => {
        cy.get('#card-number').type('4111111111111111'); // Enter valid card number
        cy.get('#expiry-date').type('12/25'); // Enter valid expiry date
        cy.get('#cvv').type('123'); // Enter valid CVV
        cy.get('#pay-button').click(); // Click on the pay button

        cy.url().should('include', '/confirmation'); // Check if redirected to confirmation page
        cy.get('.confirmation-message').should('contain', 'Thank you for your order!'); // Verify confirmation message
    });

    it('should show error message for failed payment', () => {
        cy.get('#card-number').type('4000000000000002'); // Enter invalid card number
        cy.get('#expiry-date').type('12/25'); // Enter valid expiry date
        cy.get('#cvv').type('123'); // Enter valid CVV
        cy.get('#pay-button').click(); // Click on the pay button

        cy.get('.error-message').should('contain', 'Payment failed. Please try again.'); // Verify error message
    });
});
